        else:
            cat_by_slug[cslug]['bundles'].append(lst)

memo = {}
def get_deepest_branch(u):
    if u in memo:
        return memo[u]
    children = cat_by_slug[u]['children_slugs']
    if not children:
        res = [u]
    else:
        best_child_branch = min(
            (get_deepest_branch(child) for child in children),
            key=lambda b: (-len(b), b)
        )
        res = [u] + best_child_branch
    memo[u] = res
    return res

